/* The game's static data, initialized as the original's (see gamedata.h). */
#define CIV2_GAMEDATA_DEFINE
#include <stddef.h>
#include <string.h>
#include "auto_common.h"

/* The data keeps the original's layout: one section, in address order (gcc:
   -fno-toplevel-reorder), each variable aligned as its original address and
   the bytes nothing names kept (the _rest arrays).  Code that reaches past
   one variable into the next, as the original does in places, finds what it
   found there.  gamedata_check_layout() (made by build_native.py from the
   address comments) checks it when the game starts. */
#ifdef __APPLE__
#define GAMEDATA_SECTION "__DATA,__civ2data"
#elif defined(CIV2_FIXED_DATA)
/* The unit tests' builds (tests/unit_record.c, tests/unit_run.c): a section
   of its own the link puts at a fixed address, so that pointers into the
   game's data mean the same in a recording and in later builds. */
#define GAMEDATA_SECTION "civ2data"
#else
#define GAMEDATA_SECTION ".data.civ2"
#endif
#define GAMEDATA(align) __attribute__((section(GAMEDATA_SECTION), aligned(align), used))

